#!/bin/bash
# Generated By: Claude Code (rits/deepseek-ai/DeepSeek-V4.1-Flash-1017)
#
# Rules under test:
#   1. --upload sends only paths newer than .repos[<name>].last_upload, not the
#      whole repo, so a sandbox-side edit to a file the host did not touch
#      survives the transfer.
#   2. --download tars only paths newer than the latest stamp; the host copy of
#      a file neither side touched is left alone.
#   3. The inventory diff removes what only the receiving side has: a
#      host-deleted file goes from the sandbox, a sandbox-deleted file goes
#      from the host, and a sandbox-only file goes on upload (the same wipe the
#      old pre-delete performed).
#   4. `.git` and `.venv` are excluded from deletion in both directions; only
#      --force mirrors them.
#   5. --force remains the full-tree mirror.
#   6. A file the receiving side changed more recently is not overwritten, and
#      the transfer warns once that unreconciled changes remain on the other
#      side. The warning fires even when the repo itself was skipped because
#      only one side changed.
#
# openshell is stubbed against a local directory playing /sandbox/source, so no
# gateway is needed. The stub really extracts the staged tree on upload and
# really runs the remote tar/find, which is what makes a partial transfer
# visible to the assertions.
#
# Run: tests/test-delta-transfer.sh

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "${SCRIPT_DIR}/.." && pwd)"

for tool in rsync tar jq; do
    if ! command -v "$tool" >/dev/null 2>&1; then
        echo "warning: ${tool} not installed, skipping the delta transfer checks" >&2
        echo "all delta-transfer checks passed"
        exit 0
    fi
done

TMP="$(mktemp -d)"
# shellcheck disable=SC1091 # tests/isolate.sh: fail-closed fakes, scratch HOME
source "$(dirname "${BASH_SOURCE[0]}")/isolate.sh"
trap 'rm -rf "$TMP"' EXIT

fail() { echo "FAIL: $1" >&2; exit 1; }

WORK="${TMP}/work"
mkdir -p "$WORK"
cp -r "${REPO_ROOT}/scripts" "${REPO_ROOT}/config" "${REPO_ROOT}/policies" "$WORK/"
printf 'OTEL_URL=http://x:4318\nPROMETHEUS_URL=http://x:9090\nLOKI_URL=http://x:3100\n' \
    > "${WORK}/config/site.env"

CALL_LOG="${TMP}/calls"
STAGED_LOG="${TMP}/staged"
SANDBOX_FS="${TMP}/sandboxfs"
export CALL_LOG STAGED_LOG SANDBOX_FS
mkdir -p "$SANDBOX_FS"

STUB="${TMP}/bin"
mkdir -p "$STUB"
cat > "${STUB}/openshell" << 'STUBEOF'
#!/bin/bash
echo "openshell $*" >> "$CALL_LOG"
map() {
    case "$1" in
        /sandbox/source|/sandbox/source/*) echo "${SANDBOX_FS}${1#/sandbox/source}" ;;
        # The deletion scripts carry the path inside their own text as well as
        # in argv, so substitute anywhere it appears, not only at the front.
        *"/sandbox/source"*) echo "${1//\/sandbox\/source/$SANDBOX_FS}" ;;
        *) echo "$1" ;;
    esac
}

case "$1 $2" in
    "sandbox upload")
        pos=()
        for a in "${@:3}"; do
            case "$a" in --*) ;; *) pos+=("$a") ;; esac
        done
        src="${pos[1]}"
        dest="$(map "${pos[2]}")"
        # Record what the delta actually carried, so a whole-tree upload cannot
        # pass as a partial one. Tagged with the uploaded dir's name: the
        # deletion inventory is a second upload in the same run.
        { echo "dir=$(basename "$src")"; ls -A "$src"; } >> "$STAGED_LOG"
        mkdir -p "$dest"
        # openshell extracts the tree into the destination, merging. That is
        # policy gotcha 20 and the reason a delta is safe without a pre-delete.
        cp -a "$src" "$dest/"
        ;;
    "sandbox download")
        pos=()
        for a in "${@:3}"; do [[ "$a" == --* ]] || pos+=("$a"); done
        src="$(map "${pos[1]}")"
        [[ -f "$src" ]] && cp "$src" "${pos[2]}/"
        ;;
    "sandbox exec")
        cmd=(); seen=0
        for a in "$@"; do
            [[ $seen == 1 ]] && cmd+=("$(map "$a")")
            [[ "$a" == "--" ]] && seen=1
        done
        case "${cmd[0]:-}" in
            bash)
                # HOSTILE_CONFLICT: the sandbox answers the conflict check with
                # a path that tries to escape the stage. The host must refuse it.
                if [[ -n "${HOSTILE_CONFLICT:-}" && "${cmd[*]}" == *'stat -c %Y'* ]]; then
                    printf '../../sentinel-hostile\0'
                fi
                # HOSTILE_DIRTY: a repo name the host never listed must not
                # reach the operator warning.
                if [[ -n "${HOSTILE_DIRTY:-}" && "${cmd[*]}" == *'/tmp/unrec'* ]]; then
                    echo 'DIRTY ../../evil'
                fi
                "${cmd[@]}"
                ;;
            tar|mkdir|find|rm) "${cmd[@]}" ;;
        esac
        ;;
esac
exit 0
STUBEOF
chmod +x "${STUB}/openshell"
export PATH="${STUB}:${PATH}"

HOME="${TMP}/home"
export HOME
SBX="${HOME}/sandboxes/probe"
REPO="${SBX}/myrepo"
mkdir -p "$REPO"
echo "big" > "${REPO}/big.bin"
echo "initial" > "${REPO}/edit.txt"
echo "mirror" > "${REPO}/mirror.txt"
echo "gone" > "${REPO}/gone.txt"
jq -n '{name:"probe",openshell_name:"sb-probe",profile:"personal",
        repos:{myrepo:{url:"file:///nowhere/myrepo"}}}' > "${SBX}/manifest.json"

REMOTE="${SANDBOX_FS}/myrepo"
sb() {
    ( cd "$SBX" && bash "${WORK}/scripts/sandbox.sh" "$@" ) > "${TMP}/last.log" 2>&1 \
        || { echo "sandbox.sh $* exited non-zero:" >&2; sed 's/^/    /' "${TMP}/last.log" >&2; return 1; }
}

# --- first upload has no stamp and sends the whole tree ---
# The stamp is whole-second, so the fixture must be older than it or the delta
# below would legitimately carry files written in the stamp's own second.
sleep 1
sb --upload probe
for f in big.bin edit.txt mirror.txt gone.txt; do
    [[ -f "${REMOTE}/${f}" ]] || fail "first upload did not send ${f}"
done

# --- a delta carries the changed file only, and leaves untouched files alone ---
sleep 1
echo "sandbox version" > "${REMOTE}/big.bin"
echo "sandbox only" > "${REMOTE}/sandbox-only.txt"
mkdir -p "${REMOTE}/.git"
echo keep > "${REMOTE}/.git/keepme"
sleep 1
echo "host edit" > "${REPO}/edit.txt"
: > "$STAGED_LOG"
sb --upload probe
grep -q "host edit" "${REMOTE}/edit.txt" || fail "delta upload did not send the changed file"
[[ "$(cat "${REMOTE}/big.bin")" == "sandbox version" ]] \
    || fail "delta upload overwrote a file the host had not changed"
[[ ! -e "${REMOTE}/sandbox-only.txt" ]] \
    || fail "delta upload left a path only the sandbox had"
[[ -f "${REMOTE}/.git/keepme" ]] \
    || fail "upload deletion reached .git; it must be excluded"
staged_paths="$(awk '/^dir=myrepo$/{f=1;next} /^dir=/{f=0} f' "$STAGED_LOG" | sort | tr '\n' ' ')"
[[ "$staged_paths" == "edit.txt " ]] \
    || fail "upload staged more than the changed file: ${staged_paths}"

# --- download pulls the changed file only and removes what only the host had ---
sleep 1
echo "from the sandbox" > "${REMOTE}/edit.txt"
rm -f "${REMOTE}/mirror.txt"
mkdir -p "${REPO}/.venv/bin"
echo keep > "${REPO}/.venv/bin/pyvenv.cfg"
echo "host only" > "${REPO}/host-only.txt"
sleep 1
: > "$CALL_LOG"
sb --download probe
[[ "$(cat "${REPO}/edit.txt")" == "from the sandbox" ]] \
    || fail "delta download did not bring the sandbox edit"
[[ "$(cat "${REPO}/big.bin")" == "big" ]] \
    || fail "delta download overwrote a file the sandbox had not changed"
# Newer on the host than the last agreement: this is host work, not a
# sandbox-side deletion, so it stays and the run says so.
[[ -f "${REPO}/host-only.txt" ]] \
    || fail "delta download deleted a host-only file written since the last agreement"
grep -q "Host changes not reconciled in myrepo" "${TMP}/last.log" \
    || fail "download did not warn about the kept host-only file"
[[ ! -e "${REPO}/mirror.txt" ]] \
    || fail "delta download left a sandbox-side deletion"
[[ -f "${REPO}/.venv/bin/pyvenv.cfg" ]] \
    || fail "download deletion reached .venv; it must be excluded"
grep -q -- '--newer=' "$CALL_LOG" || fail "download did not use a --newer delta tar"
grep -q 'openshell-inv-myrepo' "$CALL_LOG" \
    || fail "download tar did not carry the deletion inventory"

# --- a deletion alone is enough; no full transfer is needed ---
sleep 1
rm -f "${REPO}/gone.txt"
sb --upload probe
[[ ! -e "${REMOTE}/gone.txt" ]] || fail "upload did not remove a host-side deletion"

# --- --force stays the full mirror, .git and .venv included ---
echo remote-only > "${REMOTE}/force-only.txt"
sb --upload probe --force
[[ ! -e "${REMOTE}/force-only.txt" ]] \
    || fail "--upload --force did not mirror a sandbox-only path"

echo host-only > "${REPO}/force-host-only.txt"
sb --download probe --force
[[ ! -e "${REPO}/force-host-only.txt" ]] \
    || fail "--download --force did not mirror a host-only path"
[[ -f "${REPO}/.venv/bin/pyvenv.cfg" ]] \
    || fail "--download --force removed the host's .venv"

# --- .venv stays out of the delta, at the source ---
echo venv > "${REPO}/.venv/bin/pyvenv.cfg"
sleep 1
sb --upload probe
[[ ! -e "${REMOTE}/.venv" ]] || fail "delta upload carried .venv"

# --- a newer sandbox copy survives --upload, and the skip is reported ---
sleep 1
echo "host older" > "${REPO}/edit.txt"
sleep 1
echo "sandbox newer" > "${REMOTE}/edit.txt"
sb --upload probe
[[ "$(cat "${REMOTE}/edit.txt")" == "sandbox newer" ]] \
    || fail "delta upload overwrote a sandbox file newer than the host's"
grep -q "Sandbox changes not reconciled in myrepo" "${TMP}/last.log" \
    || fail "upload did not warn about unreconciled sandbox changes"
grep -q -- "--download brings them" "${TMP}/last.log" \
    || fail "upload warning did not name the reconciling direction"

# --force is the override.
sb --upload probe --force
[[ "$(cat "${REMOTE}/edit.txt")" == "host older" ]] \
    || fail "--upload --force did not overwrite the newer sandbox copy"

# --- a newer host copy survives --download, and the skip is reported ---
sleep 1
echo "sandbox older" > "${REMOTE}/edit.txt"
sleep 1
echo "host newer" > "${REPO}/edit.txt"
sb --download probe
[[ "$(cat "${REPO}/edit.txt")" == "host newer" ]] \
    || fail "delta download overwrote a host file newer than the sandbox's"
grep -q "Host changes not reconciled in myrepo" "${TMP}/last.log" \
    || fail "download did not warn about unreconciled host changes"
grep -q -- "--upload sends them" "${TMP}/last.log" \
    || fail "download warning did not name the reconciling direction"

sb --download probe --force
[[ "$(cat "${REPO}/edit.txt")" == "sandbox older" ]] \
    || fail "--download --force did not overwrite the newer host copy"

# --- a sandbox-only edit warns even when the host has nothing to send ---
# Settle first: the force download above rewrote edit.txt in the stamp's own
# second, which is newer than the whole-second stamp and would make this a
# delta rather than the skip the case is about.
sleep 1
sb --upload probe --force
sleep 1
echo "sandbox drift" > "${REMOTE}/drift.txt"
sb --upload probe
[[ "$(cat "${REMOTE}/drift.txt")" == "sandbox drift" ]] \
    || fail "upload removed a sandbox-only file"
[[ ! -e "${REPO}/drift.txt" ]] || fail "upload pulled a sandbox-only file to the host"
grep -q "Sandbox changes not reconciled in myrepo" "${TMP}/last.log" \
    || fail "skipped upload did not warn about sandbox-only changes"

# --- a host-only edit warns even when the sandbox has nothing to send ---
sb --upload probe --force
sleep 1
echo "host drift" > "${REPO}/host-drift.txt"
sb --download probe
[[ ! -e "${REMOTE}/host-drift.txt" ]] || fail "download pushed a host-only file to the sandbox"
grep -q "Host changes not reconciled in myrepo" "${TMP}/last.log" \
    || fail "skipped download did not warn about host-only changes"

# --- a successful delta does not warn about the paths it just sent ---
sb --upload probe --force
sleep 1
echo "host only change" > "${REPO}/host-new.txt"
sb --upload probe
[[ "$(cat "${REMOTE}/host-new.txt")" == "host only change" ]] \
    || fail "delta upload did not send a host-only file"
grep -q "Sandbox changes not reconciled in myrepo" "${TMP}/last.log" \
    && fail "upload warned about the paths it had just sent"

# Same, but the host change is a commit-shaped `.git` write.
sleep 1
mkdir -p "${REPO}/.git/objects" "${REPO}/.git/refs/heads"
echo obj > "${REPO}/.git/objects/newobject"
echo ref > "${REPO}/.git/refs/heads/main"
sb --upload probe
grep -q "Sandbox changes not reconciled in myrepo" "${TMP}/last.log" \
    && fail "upload warned about .git paths it had just sent"

# --- a sandbox-reported conflict path cannot escape the stage ---
sentinel="${TMP}/sentinel-hostile"
: > "$sentinel"
sleep 1
echo "host change" > "${REPO}/edit.txt"
HOSTILE_CONFLICT=1 sb --upload probe
[[ -f "$sentinel" ]] || fail "a sandbox-reported '../' path deleted a host file outside the stage"

# --- a sandbox-reported repo name cannot reach the warning ---
HOSTILE_DIRTY=1 sb --upload probe
grep -q "evil" "${TMP}/last.log" && fail "the warning echoed a sandbox-supplied repo name"

# --- a newer sandbox .git ref survives --upload ---
sb --upload probe --force
sleep 1
echo "host ref" > "${REPO}/.git/refs/heads/main"
sleep 1
echo "sandbox ref" > "${REMOTE}/.git/refs/heads/main"
sb --upload probe
[[ "$(cat "${REMOTE}/.git/refs/heads/main")" == "sandbox ref" ]] \
    || fail "upload overwrote a newer sandbox .git ref"
grep -q "Sandbox changes not reconciled in myrepo" "${TMP}/last.log" \
    || fail "upload did not warn about the newer sandbox .git ref"

# --- a sandbox .venv write is not unreconciled work ---
sb --upload probe --force
sleep 1
mkdir -p "${REMOTE}/.venv/lib"
echo pyc > "${REMOTE}/.venv/lib/x.pyc"
sb --upload probe
grep -q "Sandbox changes not reconciled in myrepo" "${TMP}/last.log" \
    && fail "a sandbox .venv write produced the unreconciled warning"

echo "all delta-transfer checks passed"
